  output logic [MBX_N_IF_C*MBX_N_PUB_SOURCES_C-1:0] pub_licence_o,   //! LICENCE.ACTIVE per interface
  output logic [MBX_N_IF_C*MBX_IDLE_SLOPE_BPS_WIDTH_C-1:0] pub_idle_slope_o,   //! IDLE_SLOPE.BPS per interface
