  localparam int unsigned AW2_C = MBX_ADDR_W_C + 2;   //! byte-offset width

  // ---- NOW_MS --------------------------------------------------------------
  logic [31:0] now_ms_r;
  always_ff @(posedge clk_i) begin : now_ms
    if (!rst_n) now_ms_r <= '0;
    else if (ms_tick_p_i) now_ms_r <= now_ms_r + 32'd1;
