      if (wr_w && off_w == AW2_C'(MBX_REG_TICK_CTL_C)) tick_ctl_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_TICK_CTL_EN_LSB_C, MBX_TICK_CTL_EN_WIDTH_C));
      if (wr_w && off_w == AW2_C'(MBX_REG_OWN_EID_LO_C)) own_eid_lo_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_OWN_EID_LO_EID_LSB_C, MBX_OWN_EID_LO_EID_WIDTH_C));
      if (wr_w && off_w == AW2_C'(MBX_REG_OWN_EID_HI_C)) own_eid_hi_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_OWN_EID_HI_EID_LSB_C, MBX_OWN_EID_HI_EID_WIDTH_C));
