      if (wr_w && off_w == AW2_C'(MBX_REG_MAAP_BASE_LO_C)) maap_base_lo_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_MAAP_BASE_LO_ADDR_LSB_C, MBX_MAAP_BASE_LO_ADDR_WIDTH_C));
