      if (wr_w && off_w == AW2_C'(MBX_REG_MAAP_COUNT_C)) maap_count_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_MAAP_COUNT_COUNT_LSB_C, MBX_MAAP_COUNT_COUNT_WIDTH_C));
      if (wr_w && off_w == AW2_C'(MBX_REG_TMR_DEADLINE_C)) tmr_deadline_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_TMR_DEADLINE_MS_LSB_C, MBX_TMR_DEADLINE_MS_WIDTH_C));
      if (wr_w && off_w == AW2_C'(MBX_REG_EVT_TAIL_C)) evt_tail_r <= host_wdata_i & (mbx_place_f(32'hFFFF_FFFF, MBX_EVT_TAIL_WORDS_LSB_C, MBX_EVT_TAIL_WORDS_WIDTH_C));
